<section class="soc-shell min-h-screen"><div class="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8">
<div class="dashboard-heading"><div><p class="section-label text-amber-400">Controlled laboratory</p><h1 class="text-4xl font-semibold text-slate-100">Vulnerability lab</h1><p class="mt-3 text-slate-400">Synthetic academic modules. This area is separate from real application security.</p></div><a class="button button-secondary" href="<?= e(url('/security')) ?>">Security operations</a></div>
<div class="mt-8 rounded-2xl border <?= $enabled?'border-amber-500 bg-amber-950/30':'border-slate-700 bg-slate-900' ?> p-6"><span class="text-sm uppercase tracking-widest text-slate-400">Environment-authoritative lab status</span><strong class="mt-2 block text-3xl <?= $enabled?'text-amber-300':'text-slate-300' ?>">LAB STATUS: <?= $enabled?'ENABLED':'DISABLED' ?></strong><p class="mt-2 text-sm text-slate-400">This dashboard cannot change the global environment switch.</p><?php if($enabled): ?><a class="button button-secondary mt-5 inline-flex" href="<?= e(url('/lab')) ?>">Open lab registry</a><?php else: ?><p class="mt-3 text-sm text-slate-400">Controlled exercises are unavailable while the lab is disabled.</p><?php endif; ?></div>
