<section class="mt-8 grid gap-5 lg:grid-cols-3"><?php foreach($modules as $module): $nextState=$module['state']==='VULNERABLE'?'REMEDIATED':'VULNERABLE'; ?><article class="rounded-2xl border border-slate-800 bg-slate-900 p-6"><div class="flex justify-between gap-3"><strong><?= e($module['vulnerability_identifier']) ?></strong><span class="status-badge <?= $module['state']==='VULNERABLE'?'text-amber-300':'text-emerald-400' ?>"><?= e($module['state']) ?></span></div><h2 class="mt-3 text-lg font-semibold"><?= e($module['category']) ?></h2><p class="mt-2 text-sm text-slate-400"><?= e($module['description']) ?></p><p class="mt-3 text-xs text-slate-500"><?= e($module['testing_notes']) ?></p><p class="mt-3 text-sm"><strong>Countermeasure:</strong> <?= e($module['mitigation']) ?></p><?php if($enabled && $module['is_active'] && $module['route']): ?><a class="mt-5 inline-flex text-sm font-semibold text-emerald-300 underline underline-offset-4" href="<?= e(url($module['route'])) ?>">Open <?= e($module['category']) ?> exercise</a><?php endif; ?><?php if($module['is_active']): ?><form class="mt-5" method="post" action="<?= e(url('/security/lab/modules/'.$module['id'].'/state')) ?>" data-confirm="Switch this controlled module to <?= e($nextState) ?>? This changes only the isolated academic LAB state."><?= csrf_field() ?><input type="hidden" name="state" value="<?= e($nextState) ?>"><button class="button <?= $nextState==='VULNERABLE'?'button-danger':'button-secondary' ?>" type="submit">Switch to <?= e($nextState) ?></button></form><?php endif; ?></article><?php endforeach; ?></section>
<section class="mt-8 rounded-2xl border border-slate-800 bg-slate-900 p-6"><h2 class="text-lg font-semibold">Recent controlled interactions</h2><?php if($events===[]): ?><p class="mt-3 text-slate-400">No lab interactions recorded.</p><?php else: ?><div class="mt-4 overflow-x-auto"><table class="w-full text-left text-sm"><thead class="text-slate-500"><tr><th class="py-2">Time</th><th>Event</th><th>Module</th><th>State</th><th>Delta</th></tr></thead><tbody class="divide-y divide-slate-800"><?php foreach($events as $event): ?><tr><td class="py-3"><?= e($event['created_at']) ?></td><td><?= e($event['event_type']) ?></td><td><?= e($event['metadata']['module_identifier']??'LAB') ?></td><td><?= e($event['metadata']['module_state']??$event['metadata']['to_state']??'n/a') ?></td><td><?= e((string)$event['risk_delta']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="mt-8 rounded-2xl border border-slate-800 bg-slate-900 p-6"><h2 class="text-lg font-semibold">State-change history</h2><?php if($history===[]): ?><p class="mt-3 text-slate-400">No module state changes recorded.</p><?php else: ?><div class="mt-4 space-y-2"><?php foreach($history as $change): ?><div class="rounded border border-slate-800 p-3"><strong><?= e($change['vulnerability_identifier']) ?></strong><span class="ml-3 text-slate-400"><?= e($change['from_state'].' → '.$change['to_state'].' · '.$change['created_at']) ?></span></div><?php endforeach; ?></div><?php endif; ?></section>
</div></section>
